// tiktok-business-nightly — CHỈ TikTok Ads. Kéo CHI TIÊU (spend) 7 ngày gần nhất → POST /api/ingest/ads.
// TÁCH RIÊNG khỏi Meta có chủ đích: 2 API khác nhau, token khác nhau, kiểu lỗi khác nhau.
//
// KÉO 2 LOẠI CHIẾN DỊCH — thiếu loại nào là THIẾU CHI PHÍ, và lãi sẽ bị thổi phồng:
//   (a) AUCTION  → /report/integrated/get/  (quảng cáo đấu giá thường)
//   (b) GMV MAX  → /gmv_max/report/get/     (endpoint RIÊNG, bắt buộc store_ids; report thường KHÔNG trả)
// Shop chạy CHỦ YẾU GMV Max: đo thật một cửa sổ 30 ngày: toàn bộ chi tiêu. Chỉ kéo auction ⇒ báo 0đ.
// GMV Max trừ tiền qua GMV Pay (trừ thẳng số dư TikTok Shop khi chạm ngưỡng) — đó là DÒNG TIỀN,
// KHÔNG được cộng vào chi phí lần nữa: chi phí quảng cáo chỉ lấy DUY NHẤT từ report này.
// BẤT BIẾN: TUYỆT ĐỐI không lấy GMV / conversion value / purchase_roas làm DOANH THU — doanh thu chỉ đến từ Pancake.
// Riêng `orders` (ĐẾM ĐƠN sàn tự nhận công, không phải tiền) ĐƯỢC kéo ở node GMV Max để hiển thị
// THAM KHẢO cột Đơn/CPO/GMV/ROI ở /marketing — chủ shop chốt 2026-08-21, MỞ RỘNG 2026-08-25 (lật quyết định 18/08):
// gross_revenue + roi ĐƯỢC kéo để hiển thị TRONG KHU RIÊNG có nhãn "sàn báo". TUYỆT ĐỐI không vào pnl.ts,
// không sửa phí sàn, không đối chiếu với đơn Pancake. conversion value / purchase_roas VẪN CẤM.
// BREAKDOWN GMV Max theo SẢN PHẨM (thêm 2026-08-25): sau lượt campaign-level, kéo thêm
//   dimensions = [campaign_id, item_group_id, stat_time_day] và land sang stream RIÊNG
//   `tiktokbusiness/gmvmax_item` qua /api/ingest/raw. TUYỆT ĐỐI KHÔNG đi qua /api/ingest/ads:
//   tổng cấp item THIẾU 0,60% so cấp campaign (đo 25/08: 136.355 vs 137.180) ⇒ ghi vào sổ là sai tiền.
//   Chi phí trong P&L GIỮ NGUYÊN nguồn campaign-level.
// TZ + tiền tệ: ad account Meta VÀ TikTok đều Asia/Ho_Chi_Minh + VND (chủ shop xác nhận 2026-07-14)
//   ⇒ ngày API trả về CHÍNH LÀ ngày VN, map thẳng 1:1, không cần quy đổi/re-bucket theo giờ.
//   Guard tiền tệ bên dưới vẫn giữ: ad account đổi sang tiền khác ⇒ DỪNG, không ghi số sai.
// Vì sao 7 ngày (không phải "hôm qua"): Meta/TikTok chỉnh spend hồi tố vài ngày. Upsert idempotent theo
//   refId (TIKTOK_ADS:<date>:<campaignId>) ⇒ kéo lại chỉ ghi đè đúng số, an toàn và không tốn thêm gì.
//
// VAT — HỢP ĐỒNG MỚI (2026-07-15): workflow KHÔNG nhân VAT vào spend nữa. "app lo mọi logic tiền"
// (CLAUDE.md). Ta VẪN ĐO tỉ lệ VAT từ hoá đơn thật (để đối soát + để app dùng), rồi GỬI cho
// /api/ingest/ads theo cặp { spendExVat, vatRate }; app tự tính amount = round(spendExVat*(1+vatRate)).
/**
 * Khoá lấy từ node "Lấy khoá từ bảng Setting" (mỗi dòng = 1 cặp key/value của bảng `app."Setting"`).
 * Để khoá trong bảng thay vì viết thẳng vào đây: mở bảng là xem được, đổi khoá chỉ sửa 1 ô, và
 * file workflow trong repo khớp tuyệt đối bản đang chạy nên diff được.
 */
const KHOA = Object.fromEntries($input.all().map((i) => [i.json.key, i.json.value]));
const KHOA_THIEU = ["n8nAppUrl","n8nIngestSecret","tiktokBusinessAppSecret","tiktokBusinessToken","tiktokBusinessAppId","tiktokShopShopId"].filter((k) => !KHOA[k]);
if (KHOA_THIEU.length) {
  throw new Error(
    `THIẾU KHOÁ trong bảng app."Setting": ${KHOA_THIEU.join(", ")}. Thêm dòng key/value tương ứng rồi ` +
      `chạy lại — không cần đụng file cấu hình hay dựng lại container.`
  );
}

const CONFIG = {
  appUrl: KHOA.n8nAppUrl,
  ingestSecret: KHOA.n8nIngestSecret,
  tiktok: {
    appId: KHOA.tiktokBusinessAppId,
    appSecret: KHOA.tiktokBusinessAppSecret,
    token: KHOA.tiktokBusinessToken,
    // BẮT BUỘC cho report GMV Max — id shop TikTok Shop (KHÁC id shop TikTok bên Pancake).
    storeId: KHOA.tiktokShopShopId,
  },
  // Cửa sổ mặc định 7 ngày (sàn chỉnh spend hồi tố vài ngày). Cần kéo rộng hơn thì thêm key
  // `tiktokBusinessManualDays` (SỐ NGUYÊN 1–60) vào bảng Setting, ĐỪNG sửa số ở đây — xem ghi
  // chú "Cửa sổ ngày" dưới.
  nightlyDays: 7,
};

const http = this.helpers.httpRequest;
const DAY = 86400000;
const CHUNK = 500; // /api/ingest/ads chặn tối đa 2000 dòng mỗi lần POST
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// 429 (rate limit) và 5xx là lỗi TẠM THỜI của phía TikTok, KHÔNG phải lỗi của ta. Ném luôn = giết cả
// lượt sync đêm chỉ vì một cú nghẽn ⇒ MẤT toàn bộ chi phí ads đêm đó. Lùi rồi thử lại: 3s → 8s → 20s.
// (Cửa sổ ép rộng × nhiều advertiser bắn hàng chục request liên tiếp nên chạm 429 là chuyện thường —
//  bê pattern từ tiktokshop-nightly.)
const BACKOFF_MS = [3000, 8000, 20000];
function laLoiTamThoi(err) {
  const code = String((err && (err.httpCode || err.statusCode || (err.response && err.response.status))) || "");
  const msg = (err && err.message) || String(err);
  return code === "429" || /^5\d\d$/.test(code) || /status code (429|5\d\d)/.test(msg);
}

// Ngày theo GIỜ VN, KHÔNG theo TZ container n8n. en-CA ⇒ đúng định dạng "YYYY-MM-DD".
const vnFmt = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Ho_Chi_Minh",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});
const vnDate = (ms) => vnFmt.format(new Date(ms));
// Cửa sổ ngày — MỘT nguồn duy nhất: key `tiktokBusinessManualDays` trong bảng Setting ép cửa sổ cho
// MỌI lượt (theo lịch lẫn bấm tay); không có key thì dùng `nightlyDays`.
//
// Trước đây có nhánh "chạy theo lịch ⇒ 7 ngày, bấm tay ⇒ backfill 60 ngày" nhận diện bằng
// `$execution.mode === "trigger"`, kèm ghi chú khẳng định n8n không có mode nào tên "test".
// ĐO THẬT 26/07/2026, đo lại 01/08/2026 — biến này trong Code node CHỈ nhận 2 giá trị: lịch cron ⇒
// "production" (execution 104563), bấm tay ⇒ "test" (execution 104562). KHÔNG bao giờ là "trigger":
// đó là nhãn của REST /executions, khác hẳn biến trong Code node, và chính chỗ nhầm hai thứ đó đẻ ra
// lỗi này. Điều kiện cũ SAI với CẢ HAI chế độ ⇒ `lookbackDays: 7` là code chết, MỖI ĐÊM đều rơi vào
// nhánh backfill 60 ngày (2 lát 30 ngày × mỗi advertiser × 2 endpoint report — tốn request vô ích,
// dễ chạm 429). Hậu quả chờ nổ giống hệt Meta: app tính `amount = spendExVat × (1 + vatRate)`, mà
// `vatRate` ở đây ĐO TỪ HOÁ ĐƠN TRONG KỲ — cửa sổ rộng lấy nhầm thuế của kỳ khác là ghi đè 2 tháng
// chi phí lịch sử bằng thuế suất sai, lợi nhuận kỳ quá khứ nhảy số. Nay mặc định LUÔN là cửa sổ hẹp:
// mọi hiểu nhầm về chế độ chạy đều rơi về phía an toàn, và `execMode` cuối lượt in giá trị thô để
// lần sau khỏi phải suy đoán.
//
// Cần backfill: đặt `tiktokBusinessManualDays` = N → chạy tay → TRẢ KEY VỀ 7 (hoặc xoá key).
//
// ⚠️ TRƯỚC KHI ĐẶT N: `tinhVat()` đo MỘT suất từ hoá đơn trong kỳ rồi áp cho mọi dòng của cửa sổ,
// nên N ngày phải nằm TRỌN trong một chế độ thuế suất. Cắt qua ngày đổi thuế là ghi lại phần bên
// kia mốc bằng suất của kỳ khác — sai âm thầm.
//
// KHÔNG CÓ CÁCH lấy riêng phần TRƯỚC mốc đổi thuế — đừng thử "chia nhiều lượt hẹp hơn": `until`
// neo cứng vào HÔM QUA rồi trừ ngược ra `since`, không có tham số mốc kết thúc, nên mọi cửa sổ
// đều bám mép hiện tại và không cửa sổ nào nằm trọn trong quá khứ. Cần phần cũ thì phải thêm mốc
// kết thúc, hoặc làm VAT theo ngày hiệu lực (việc còn treo, xem docs/lo-trinh-du-an.md).
//
// TRẦN 60 NGÀY — trần CHẶT NHẤT trong ba workflow, và lý do không phải rate-limit mà là VAT:
// `tinhVat()` đo MỘT thuế suất từ hoá đơn TRONG KỲ rồi áp CHUNG cho mọi dòng của cửa sổ. Cửa
// sổ càng rộng càng trộn hoá đơn nhiều kỳ, và app tính `amount = spendExVat × (1 + vatRate)`
// ⇒ ghi đè chi phí lịch sử bằng thuế suất trung bình sai, lợi nhuận kỳ cũ nhảy số. 60 ngày là
// đúng 2 lát (TikTok chặn cứng 30 ngày mỗi call) và giữ lượt chạy nhẹ.
//
// ⚠️ ĐỪNG đọc "60 ngày = tối đa 2 kỳ hoá đơn": cửa sổ trôi tự do theo ngày chạy nên 60 ngày
// thường trải BA tháng dương lịch (vd 15/01 → 15/03) và nhiều hoá đơn. Trần này chỉ giảm bớt
// rủi ro, KHÔNG bảo đảm VAT đúng — điều kiện thật là cả khoảng nằm trong một chế độ thuế suất.
// Muốn dựng lại xa hơn (dòng TIKTOK_ADS xa nhất trên prod cũ hơn trần) thì phải nâng trần CÓ
// CHỦ ĐÍCH và chấp nhận rủi ro VAT trộn kỳ ở trên.
const MAX_MANUAL_DAYS = 60;

/**
 * Đọc số ngày ép từ một ô của bảng Setting. Trả 0 = KHÔNG ép (dùng `nightlyDays`).
 * CHỈ nhận số nguyên từ 1 đến `tran`; mọi giá trị khác ⇒ THROW.
 *
 * Vì sao không còn `Number(x) > 0` như bản trước: `"7.5"` cho mốc `since` lệch nửa ngày (sau này
 * rất khó truy ra vì sao thiếu/thừa một ngày), `"Infinity"` làm chính bước tính ngày NỔ giữa đêm
 * (đo 03/08/2026: workflow dùng `Intl.DateTimeFormat` ném `RangeError: Invalid time value`, workflow
 * dùng mốc epoch thì gửi lên API một cửa sổ vô nghĩa), `"100000"` bắn hàng nghìn request (chạm rate-limit và
 * trần 3600s của runner — N8N_RUNNERS_TASK_TIMEOUT), còn `"abc"` hay số âm thì rơi về mặc định
 * TRONG IM LẶNG: người vận hành đặt key xong tưởng đã backfill mà thực ra không.
 *
 * Vì sao THROW chứ không âm thầm về mặc định kèm cảnh báo: giá trị sai LUÔN do người vừa sửa bảng
 * Setting gõ nhầm — họ đang ở đó và thấy ngay execution FAILED. Hỏng một đêm KHÔNG mất dữ liệu:
 * cửa sổ thường trực là 7 ngày và Bronze dedupe theo hash nên lượt sau phủ lại phần thiếu.
 */
function soNgayCuaSo(key, giaTri, tran) {
  const s = String(giaTri === undefined || giaTri === null ? "" : giaTri).trim();
  if (s === "") return 0;
  if (!/^[0-9]+$/.test(s) || Number(s) < 1 || Number(s) > tran) {
    throw new Error(
      "Key " + key + ' = "' + s + '" KHÔNG hợp lệ — chỉ nhận SỐ NGUYÊN từ 1 đến ' + tran +
        " (không thập phân, không số âm, không chữ, không Infinity). Sửa lại ô đó trong bảng " +
        'app."Setting", hoặc XOÁ/để trống nó để quay về cửa sổ mặc định, rồi chạy lại.'
    );
  }
  return Number(s);
}

const soNgayEp = soNgayCuaSo("tiktokBusinessManualDays", KHOA.tiktokBusinessManualDays, MAX_MANUAL_DAYS);
const soNgay = soNgayEp > 0 ? soNgayEp : CONFIG.nightlyDays;
const now = Date.now();
const until = vnDate(now - DAY); // hôm qua (giờ VN)
const since = vnDate(now - soNgay * DAY); // giờ VN

const log = (m) => console.log("[tiktok-business] " + m);
const tokenErr = (source, detail) =>
  new Error(
    "TOKEN HẾT HẠN — " + source + ": " + detail +
      " — tạo token mới rồi cập nhật CONFIG trong node này (token Meta sống tối đa 60 ngày).",
  );
const currencyErr = (source, cur) =>
  new Error(
    "SAI TIỀN TỆ — " + source + ": ad account đang dùng '" + cur +
      "', không phải VND. Chi phí sẽ sai ~26.000 lần ⇒ DỪNG, không ghi dữ liệu.",
  );

async function postRows(source, rows) {
  if (!rows.length) {
    log(source + ": 0 dòng cho " + since + " → " + until +
      " (không campaign nào có report, hoặc sai account/advertiser id) — không POST.");
    return { source, rows: 0, upserted: 0, note: "rỗng" };
  }
  let upserted = 0;
  for (let i = 0; i < rows.length; i += CHUNK) {
    const chunk = rows.slice(i, i + CHUNK);
    const r = await http({
      method: "POST",
      url: CONFIG.appUrl + "/api/ingest/ads",
      headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
      body: { source, rows: chunk },
      json: true,
    });
    upserted += (r && r.stats && Number(r.stats.rowsUpserted)) || 0;
  }
  log(source + ": " + rows.length + " dòng (" + since + " → " + until + "), app upsert " + upserted);
  return { source, rows: rows.length, upserted };
}


/**
 * TikTok CHẶN CỨNG 30 ngày mỗi lần gọi khi dùng dimension stat_time_day (code 40002).
 * Cửa sổ ép rộng hơn 30 ngày ⇒ PHẢI chia lát ≤30 ngày, không chia thì MỌI advertiser đều lỗi.
 */
const MAX_SPAN_DAYS = 30;
function chiaLat(sinceStr, untilStr) {
  const lat = [];
  let s = new Date(sinceStr + "T00:00:00Z").getTime();
  const e = new Date(untilStr + "T00:00:00Z").getTime();
  while (s <= e) {
    const end = Math.min(s + (MAX_SPAN_DAYS - 1) * DAY, e);
    lat.push({ start: new Date(s).toISOString().slice(0, 10), end: new Date(end).toISOString().slice(0, 10) });
    s = end + DAY;
  }
  return lat;
}

// ---------- TIKTOK ----------
// TikTok trả HTTP 200 kèm body.code ≠ 0 khi lỗi ⇒ phải soi code, không chỉ soi HTTP status.
// 429/5xx (ném ở tầng HTTP) là lỗi TẠM THỜI ⇒ lùi rồi thử lại thay vì giết cả lượt.
async function tiktokGet(path, qs) {
  let res;
  for (let lanThu = 0; ; lanThu++) {
    try {
      res = await http({
        method: "GET",
        url: "https://business-api.tiktok.com/open_api/v1.3" + path,
        headers: { "Access-Token": CONFIG.tiktok.token },
        qs,
        json: true,
      });
      break;
    } catch (e) {
      if (laLoiTamThoi(e) && lanThu < BACKOFF_MS.length) {
        const cho = BACKOFF_MS[lanThu];
        log(path + ": TikTok nghẽn (429/5xx), chờ " + cho / 1000 + "s rồi thử lại (lần " +
          (lanThu + 1) + "/" + BACKOFF_MS.length + ")");
        await sleep(cho);
        continue;
      }
      const body = (e && e.response && e.response.body) || {};
      res = body && body.code !== undefined ? body : { code: -1, message: (e && e.message) || String(e) };
      break;
    }
  }
  const code = Number(res && res.code);
  const msg = (res && res.message) || "không rõ";
  if (code !== 0) {
    // 40105 = access token sai/bị thu hồi. Mã auth khác bắt qua regex message.
    if (code === 40105 || /token|auth|permission|credential|revok|expire/i.test(msg)) {
      throw tokenErr("TIKTOK_ADS", "code " + code + " — " + msg);
    }
    throw new Error("TIKTOK_ADS lỗi: code " + code + " — " + msg);
  }
  return res.data || {};
}

/**
 * MỌI advertiser đã cấp quyền — KHÔNG ghim 1 id.
 * Shop có 7 tài khoản quảng cáo (đo 2026-07-14: chỉ "Hogikids" 7129548444015902722 đang tiêu tiền).
 * Ghim cứng 1 id ⇒ hôm nào chủ shop chạy ads từ tài khoản khác là P&L MẤT chi phí đó trong im lặng,
 * và lãi tự nhiên đẹp lên. Quét hết chỉ tốn vài request/đêm.
 */
async function layAdvertisers() {
  const data = await tiktokGet("/oauth2/advertiser/get/", {
    app_id: CONFIG.tiktok.appId,
    secret: CONFIG.tiktok.appSecret,
  });
  const list = (data && data.list) || [];
  if (!list.length) throw new Error("TIKTOK_ADS: không có advertiser nào được cấp quyền — kiểm lại token/app.");
  return list.map((a) => ({ id: String(a.advertiser_id), name: a.advertiser_name || "" }));
}

/** Guard tiền tệ: đọc currency TRƯỚC khi tin bất kỳ con số spend nào. Không phải VND ⇒ DỪNG. */
async function kiemTienTe(adv) {
  const info = await tiktokGet("/advertiser/info/", {
    advertiser_ids: JSON.stringify([adv.id]),
    fields: JSON.stringify(["advertiser_id", "currency", "timezone"]),
  });
  const acc = ((info && info.list) || [])[0] || {};
  const currency = String(acc.currency || "");
  if (!currency) throw new Error("TIKTOK_ADS: không đọc được currency của advertiser " + adv.id + " ⇒ DỪNG.");
  if (currency !== "VND") throw currencyErr("TIKTOK_ADS (" + adv.name + ")", currency);
}


/**
 * Land BẢN GỐC (TEXT THÔ) báo cáo ads vào Bronze — song song với đường ghi Expense.
 * `shopId` của stream này = advertiser_id. Bronze CHỈ để lưu trữ/dựng lại; chi phí vào P&L vẫn đi
 * qua /api/ingest/ads (Expense). Hai đường KHÔNG cộng dồn — cộng cả hai là đếm 2 lần chi phí. Land
 * raw KHÔNG tự ghi Expense: app chỉ dựng lại chi phí từ kho thô khi chủ shop bấm "Dựng lại từ kho
 * thô".
 *
 * Land hỏng KHÔNG được giết cả lượt: Expense (số vào P&L) mới là thứ bắt buộc. Ghi cảnh báo rồi đi
 * tiếp. Đánh đổi phải biết: trang land hỏng là trang MẤT khả năng dựng lại (sổ có số, kho thô không
 * có gốc — app gọi là "ads mồ côi" và đếm ở dialog xoá dữ liệu).
 */
async function landRaw(stream, shopId, text) {
  try {
    const r = await http({
      method: "POST",
      url: CONFIG.appUrl + "/api/ingest/raw",
      json: true,
      headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
      body: { stream: stream, shopId: shopId, payload: text },
    });
    return (r && r.stats && Number(r.stats.landed)) || 0;
  } catch (e) {
    log("CẢNH BÁO: land raw hỏng (" + stream + "/" + shopId + "): " + ((e && e.message) || String(e)));
    return -1;
  }
}

/**
 * Lấy TEXT THÔ để land Bronze. `encoding:"text"` là BẮT BUỘC: `json:false` một mình chỉ đổi header
 * Accept, axios vẫn JSON.parse body. Với ads thì campaign_id là CHUỖI nên parse không hỏng khoá,
 * nhưng Bronze phải giữ ĐÚNG bản gốc — không để n8n chuẩn hoá lại (đổi thứ tự key ⇒ đổi hash ⇒ dedupe hỏng).
 * Đây là đường CHÍNH lấy dữ liệu (một lần gọi, dùng cho cả Bronze lẫn Expense) ⇒ lỗi phải THROW.
 * 429/5xx là lỗi TẠM THỜI ⇒ lùi rồi thử lại (không giết cả lượt vì một cú nghẽn).
 */
async function tiktokGetText(path, qs) {
  for (let lanThu = 0; ; lanThu++) {
    try {
      const text = await http({
        method: "GET",
        url: "https://business-api.tiktok.com/open_api/v1.3" + path,
        headers: { "Access-Token": CONFIG.tiktok.token },
        qs,
        json: false,
        encoding: "text",
      });
      if (typeof text !== "string") {
        throw new Error("n8n trả object cho " + path + ", không phải TEXT thô — thiếu encoding:'text'.");
      }
      return text;
    } catch (e) {
      if (laLoiTamThoi(e) && lanThu < BACKOFF_MS.length) {
        const cho = BACKOFF_MS[lanThu];
        log(path + ": TikTok nghẽn (429/5xx), chờ " + cho / 1000 + "s rồi thử lại (lần " +
          (lanThu + 1) + "/" + BACKOFF_MS.length + ")");
        await sleep(cho);
        continue;
      }
      throw e;
    }
  }
}

/**
 * Đọc envelope TikTok từ chuỗi thô. TikTok trả HTTP 200 kèm `code` ≠ 0 khi lỗi ⇒ phải soi `code`.
 * Token chết ⇒ KÊU TO (hệ cũ nuốt lỗi nên token chết 12 ngày không ai biết).
 */
function docJson(path, text) {
  let res;
  try {
    res = JSON.parse(text);
  } catch (e) {
    throw new Error("TIKTOK_ADS " + path + ": body không phải JSON: " + String(text).slice(0, 120));
  }
  const code = Number(res && res.code);
  const msg = (res && res.message) || "không rõ";
  if (code !== 0) {
    if (code === 40105 || /token|auth|permission|credential|revok|expire/i.test(msg)) {
      throw tokenErr("TIKTOK_ADS", "code " + code + " — " + msg);
    }
    throw new Error("TIKTOK_ADS lỗi: code " + code + " — " + msg);
  }
  return res.data || {};
}

/**
 * Gom chi tiêu theo NGÀY từ 1 endpoint report. Thiếu dimension stat_time_day ⇒ TikTok gộp cả kỳ.
 * GỬI CẢ dòng spend=0 (không lọc bỏ): nếu campaign trước có chi mà nay report trả 0, app cần dòng 0
 * để HẠ Expense của campaign đó về 0. Lọc 0 ở đây ⇒ Expense giữ số cũ ⇒ chi phí thừa (lãi ảo thấp đi).
 */
async function keoReport(adv, path, extra, tenMetric, adType) {
  const rows = [];
  let landed = 0;
  for (const lat of chiaLat(since, until)) {
  for (let page = 1; page <= 50; page++) {
    const qs = Object.assign({
      advertiser_id: adv.id,
      report_type: "BASIC",
      dimensions: JSON.stringify(["campaign_id", "stat_time_day"]),
      start_date: lat.start,
      end_date: lat.end,
      page: page,
      page_size: 1000,
    }, extra);
    // MỘT lần gọi cho cả 2 việc: land bản gốc vào Bronze + parse ra dòng chi phí cho Expense.
    // Gọi 2 lần (object + text) là gấp đôi request → dính 429 mà chẳng được gì.
    // Parse an toàn: campaign_id của TikTok là CHUỖI trong JSON (đã kiểm) — không có int64 trần.
    const raw = await tiktokGetText(path, qs);
    // Kiểm mã lỗi TRƯỚC khi land (như keoHoaDon): không land body lỗi ⇒ không đẻ SyncLog ERROR oan.
    const data = docJson(path, raw);
    const list = data.list || [];
    // Lát/advertiser KHÔNG có campaign nào: TikTok BỎ HẲN khoá `list` chứ không trả mảng rỗng (đo
    // checkpoint P2 25/08) ⇒ landRaw ném "envelope không có mảng tại data.list", thông điệp đổ oan
    // "hết hạn key / token / rate-limit" — đúng thứ làm người đọc log giữa đêm đi sai hướng. Trang
    // rỗng thì KHÔNG land (không có gì để land) nhưng TUYỆT ĐỐI KHÔNG DỪNG lát ngay tại đây — trang
    // rỗng có thể nằm GIỮA CHỪNG (vd trang 2 rỗng, total_page = 3): dừng lát DUY NHẤT theo total_page
    // ở dưới; dừng theo mảng rỗng sẽ bỏ sót các trang sau, cắt cụt chi tiêu trong im lặng.
    if (list.length) {
      const n = await landRaw("tiktokbusiness/report", adv.id, raw);
      if (n > 0) landed += n;
      for (const x of list) {
        const dim = x.dimensions || {};
        const met = x.metrics || {};
        const spend = Number(met[tenMetric] || 0);
        rows.push({
          date: String(dim.stat_time_day || "").slice(0, 10), // TZ ad account = VN ⇒ đúng ngày VN
          campaignId: String(dim.campaign_id || ""),
          campaignName: met.campaign_name || "",
          adType: adType, // "auction" | "gmv_max" — app tách refId (auction mang infix), 1 campaign chạy CẢ 2 loại cùng ngày không đè nhau
          spend: spend, // CHƯA VAT — app nhân VAT theo hợp đồng { spendExVat, vatRate }
        });
      }
    }
    const totalPage = Number((data.page_info && data.page_info.total_page) || 1);
    if (page >= totalPage) break;
    if (page === 50) throw new Error("TIKTOK_ADS " + path + ": quá 50 trang — DỪNG, nghi phân trang không dừng.");
  }
  }
  const bad = rows.filter((r) => !/^\d{4}-\d{2}-\d{2}$/.test(r.date) || !r.campaignId);
  if (bad.length) {
    throw new Error("TIKTOK_ADS " + path + ": " + bad.length + " dòng thiếu stat_time_day/campaign_id — DỪNG.");
  }
  if (landed > 0) log(adv.name + " " + path + ": land " + landed + " dòng raw vào Bronze");
  return rows;
}


/** Trần id mỗi lô `filtering.campaign_ids`. API chặn ở 100 (checkpoint P2: 100 OK, 101 gãy); 40 để chừa biên. */
const ITEM_CHUNK = 40;

/**
 * BREAKDOWN GMV Max theo SẢN PHẨM (`item_group_id` = `Product.code` của app — đo 50/50 trên prod).
 *
 * CHỈ để trả lời "sản phẩm nào ngốn tiền" ở /marketing. KHÔNG vào Expense, KHÔNG vào P&L:
 * tổng cấp item thiếu 0,60% so cấp campaign, và `cost` ở đây CHƯA VAT.
 *
 * API bắt buộc `filtering.campaign_ids` ≥ 1 (40002 "Item level report must have at least 1 campaign
 * ID") ⇒ phải chạy SAU lượt campaign-level để biết id. Chỉ gửi campaign CÓ CHI trong cửa sổ.
 *
 * KHÔNG khai `item_id` ở đây: đo P0 cho thấy 20/31 dòng có `item_id = "-1"` (Smart Creative, không
 * gắn video) và response KHÔNG echo `item_group_id` khi hỏi `item_id` một mình ⇒ dòng không định
 * danh được. Cấp creative nằm ngoài phạm vi đợt này.
 */
async function keoItemGmvMax(adv, campaignIds) {
  if (!campaignIds.length) return 0;
  const path = "/gmv_max/report/get/";
  let landed = 0;
  for (const lat of chiaLat(since, until)) {
    for (let i = 0; i < campaignIds.length; i += ITEM_CHUNK) {
      const lo = campaignIds.slice(i, i + ITEM_CHUNK);
      for (let page = 1; page <= 50; page++) {
        const qs = {
          advertiser_id: adv.id,
          report_type: "BASIC",
          store_ids: JSON.stringify([CONFIG.tiktok.storeId]),
          dimensions: JSON.stringify(["campaign_id", "item_group_id", "stat_time_day"]),
          // Đúng 5 metric mà cấp item chấp nhận (đo P0). Xin thêm impressions/clicks/ctr/campaign_name
          // là 40002 cho CẢ lô — GMV Max không bao giờ trả chỉ số hiển thị, kể cả cấp creative.
          metrics: JSON.stringify(["cost", "orders", "cost_per_order", "gross_revenue", "roi"]),
          filtering: JSON.stringify({ campaign_ids: lo }),
          start_date: lat.start,
          end_date: lat.end,
          page: page,
          // 50 = số ĐÃ ĐO ở P0 cấp item (281 dòng / 6 trang). Cấp campaign chạy 1000 thật, nhưng
          // CÙNG endpoint KHÔNG bảo chứng CÙNG TRẦN khi đổi `dimensions` — nâng lên chỉ sau khi có
          // lượt chạy thật xác nhận trần. Shop chỉ ~1 campaign có chi mỗi đêm nên thêm trang tốn
          // gần như 0 request; đổi lại tránh execution ĐỎ kinh niên trên chính workflow đang giữ
          // đường ghi chi phí.
          page_size: 50,
        };
        const raw = await tiktokGetText(path, qs);
        const data = docJson(path, raw); // soi code TRƯỚC khi land — không land body lỗi
        const list = data.list || [];
        // Lô KHÔNG có dòng nào (lô toàn campaign không chi trong lát này) — chuyện thường vì lô chia
        // theo CẢ cửa sổ còn truy vấn chạy theo TỪNG LÁT. Trang 0 record thì TikTok BỎ HẲN khoá
        // `list` chứ không trả mảng rỗng (đo checkpoint P2 25/08) ⇒ gọi land sẽ ném "envelope không
        // có mảng tại data.list", thông điệp đổ oan token/rate-limit. Trang rỗng KHÔNG land nhưng
        // TUYỆT ĐỐI KHÔNG DỪNG lô ngay tại đây — trang rỗng có thể nằm GIỮA CHỪNG (total_page còn
        // lớn hơn trang hiện tại): dừng lô DUY NHẤT theo total_page ở dưới, không theo mảng rỗng.
        if (list.length) {
          const n = await landRaw("tiktokbusiness/gmvmax_item", adv.id, raw);
          if (n > 0) landed += n;
        }
        const totalPage = Number((data.page_info && data.page_info.total_page) || 1);
        if (page >= totalPage) break;
        if (page === 50) throw new Error("TIKTOK_ADS " + path + " (item): quá 50 trang — DỪNG, nghi phân trang không dừng.");
      }
    }
  }
  return landed;
}

// ---------- HOÁ ĐƠN + VAT ----------
/**
 * TIỀN THỰC TRẢ cho quảng cáo = `amount` của hoá đơn = `subtotal` + `tax_amount` (VAT).
 * `cost` trong report ads là số CHƯA THUẾ ⇒ ghi P&L theo report là THIẾU 10% chi phí.
 *
 * Ba nguồn nối liền nhau (kiểm chứng trên hoá đơn thật 12–16/06/2026):
 *   report cost (chưa VAT) → hoá đơn amount = cost × 1,1 (gồm VAT) → statement TikTok Shop
 *   trừ đúng số đó vào số dư (GMV_PAYMENT_FOR_TIKTOK_ADS).
 * ⇒ "ngưỡng thanh toán" mà TikTok trừ chính là hoá đơn ĐÃ GỒM THUẾ.
 *
 * Tỉ lệ VAT ĐO TỪ HOÁ ĐƠN, KHÔNG hardcode. Hardcode 1.1 là sai âm thầm vào ngày nhà nước đổi thuế
 * suất. Số này GỬI cho app (vatRate) — app nhân, không nhân ở đây (CLAUDE.md: app lo mọi logic tiền).
 *
 * ⚠️ "Tự bám theo thuế mới" CHỈ ĐÚNG khi TOÀN BỘ cửa sổ thuộc CÙNG một chế độ thuế. Hàm này đo MỘT
 * suất tổng hợp từ các hoá đơn trong kỳ rồi áp cho MỌI dòng, nên một cửa sổ cắt qua ngày đổi thuế
 * (5%/8%/10%) sẽ trộn hai chế độ thành một số rồi ghi đè cả hai phía bằng số đó — sai âm thầm, không
 * cảnh báo nào. Đó là lý do mọi lượt backfill phải tự kiểm điều kiện cửa sổ trước khi chạy (xem khối
 * "Cần backfill" ở trên). Tra thuế theo NGÀY vẫn là việc còn treo — xem docs/lo-trinh-du-an.md.
 */
const VAT_MAC_DINH = 0.10;      // chỉ dùng khi kỳ này KHÔNG có hoá đơn nào (shop ngừng chạy ads)
const VAT_TRAN_DUOI = 0.03;     // ngoài dải này là bất thường ⇒ DỪNG, không ghi số sai vào sổ
const VAT_TRAN_TREN = 0.20;

/**
 * bc_id (Business Center) — MỌI endpoint tài chính bên Business đều BẮT BUỘC có. Thiếu nó API báo
 * lỗi trông y hệt mất quyền (40002), rất dễ kết luận nhầm.
 *
 * Shop có NHIỀU Business Center (đo thật: nhiều hơn 1). Chỉ lấy list[0] ⇒ hoá đơn của BC còn lại
 * BỊ BỎ ⇒ VAT đo THIẾU (sai âm thầm trong dải cho phép). ⇒ Trả HẾT bc_id, kéo hoá đơn của TẤT CẢ.
 */
async function layBcIds() {
  const data = await tiktokGet("/bc/get/", { page_size: 50 });
  const list = (data && data.list) || [];
  const bcs = list
    .map((bc) => bc && bc.bc_info && bc.bc_info.bc_id)
    .filter(Boolean)
    .map(String);
  if (!bcs.length) {
    throw new Error("TIKTOK_BUSINESS: không lấy được bc_id nào (/bc/get/) — không đọc được hoá đơn quảng cáo.");
  }
  // Trang > 1 ⇒ đang bỏ sót BC trong im lặng ⇒ VAT đo thiếu. KÊU TO thay vì lược bớt.
  const totalPage = Number((data.page_info && data.page_info.total_page) || 1);
  if (totalPage > 1) {
    throw new Error("TIKTOK_BUSINESS: /bc/get/ có " + totalPage + " trang — đang bỏ sót Business Center, " +
      "nâng page_size hoặc thêm phân trang (VAT sẽ đo thiếu nếu bỏ sót BC).");
  }
  return bcs;
}

/** Kéo HẾT hoá đơn quảng cáo của 1 BC + land bản gốc vào Bronze. Trả mảng hoá đơn đã parse. */
async function keoHoaDon(bcId) {
  const hoaDon = [];
  for (let page = 1; page <= 50; page++) {
    const qs = { bc_id: bcId, page: page, page_size: 50 };
    const raw = await tiktokGetText("/bc/account/transaction/get/", qs);
    // Kiểm mã lỗi TRƯỚC khi land: BC thiếu quyền finance (40002) trả body lỗi (không có
    // transaction_list). docJson ném ở đây ⇒ keoHoaDon ném ⇒ vòng bcIds skip BC, KHÔNG land
    // body lỗi (land nó ⇒ app từ chối đúng ⇒ SyncLog ERROR oan ⇒ banner đỏ giả).
    const data = docJson("/bc/account/transaction/get/", raw);
    await landRaw("tiktokbusiness/invoice", bcId, raw);
    const list = data.transaction_list || data.list || [];
    for (const t of list) hoaDon.push(t);
    const totalPage = Number((data.page_info && data.page_info.total_page) || 1);
    if (page >= totalPage) break;
    if (page === 50) throw new Error("TIKTOK_BUSINESS hoá đơn (bc " + bcId + "): quá 50 trang — DỪNG.");
  }
  return hoaDon;
}

/**
 * Tỉ lệ VAT đo từ hoá đơn TRONG KỲ (đã lọc theo cửa sổ [since, until] ở ngoài).
 * Ngoài dải cho phép ⇒ THROW (không ghi số sai vào sổ chi phí).
 */
function tinhVat(hoaDon) {
  let sub = 0;
  let thue = 0;
  for (const t of hoaDon) {
    if (!/BILL|PAYMENT/i.test(String(t.transaction_type))) continue;
    sub += Math.abs(Number(t.subtotal || 0));
    thue += Math.abs(Number(t.tax_amount || 0));
  }
  if (!sub) {
    // sub===0 có 2 nguyên nhân RẤT KHÁC nhau:
    //  - kỳ này KHÔNG có hoá đơn nào (shop ngừng chạy ads) ⇒ dùng VAT mặc định là hợp lý.
    //  - CÓ hoá đơn trong kỳ nhưng regex transaction_type KHÔNG khớp cái nào ⇒ mapping đã TRÔI
    //    (API đổi tên loại giao dịch). Rơi về mặc định 10% = ghi VAT sai âm thầm ⇒ THROW.
    if (hoaDon.length) {
      throw new Error(
        "TIKTOK_BUSINESS: có " + hoaDon.length + " hoá đơn trong kỳ nhưng KHÔNG khớp BILL|PAYMENT nào " +
        "(subtotal=0) — nghi API đổi tên transaction_type ⇒ DỪNG, không ghi VAT mặc định sai vào sổ."
      );
    }
    log("Không có hoá đơn quảng cáo nào trong kỳ → dùng VAT mặc định " + (VAT_MAC_DINH * 100) + "%");
    return VAT_MAC_DINH;
  }
  const rate = thue / sub;
  if (rate < VAT_TRAN_DUOI || rate > VAT_TRAN_TREN) {
    throw new Error(
      "TIKTOK_BUSINESS: tỉ lệ VAT đo được " + (rate * 100).toFixed(2) + "% nằm ngoài dải cho phép " +
      (VAT_TRAN_DUOI * 100) + "–" + (VAT_TRAN_TREN * 100) + "% ⇒ DỪNG, không ghi chi phí sai vào sổ."
    );
  }
  log("VAT đo từ " + hoaDon.length + " hoá đơn trong kỳ: " + (rate * 100).toFixed(2) + "%");
  return rate;
}

// ---------- CHẠY ----------
// Mỗi advertiser: guard tiền tệ → auction (/report/integrated/get/) + GMV MAX (/gmv_max/report/get/).
// GMV Max nằm ở ENDPOINT RIÊNG và metric tên `cost` (không phải `spend`) — thiếu nó là mất phần lớn
// chi phí quảng cáo của shop (đo 15/05–16/06: toàn bộ chi tiêu toàn bộ là GMV Max, auction = 0đ).

// Hoá đơn: kéo của TẤT CẢ Business Center, rồi CHỈ giữ hoá đơn TẠO TRONG cửa sổ [since, until] để
// đo VAT (trộn 2 thời kỳ thuế = sai âm thầm). Lọc theo create_time (chuỗi "YYYY-MM-DD HH:MM:SS").
const bcIds = await layBcIds();
log("Business Center: " + bcIds.length + " cái (" + bcIds.join(", ") + ")");
let hoaDonTatCa = [];
const bcBoQua = [];
for (const bcId of bcIds) {
  try {
    hoaDonTatCa = hoaDonTatCa.concat(await keoHoaDon(bcId));
  } catch (e) {
    const msg = (e && e.message) || String(e);
    // BC thiếu quyền finance (40002): token đọc được BC này nhưng KHÔNG có vai trò tài chính ⇒
    // không đọc được hoá đơn BC đó. KHÔNG giết cả lượt — bỏ qua BC này, đo VAT từ BC còn đọc được.
    // Lỗi KHÁC (token thật chết 40105, mạng, mapping trôi) ⇒ ném tiếp để báo đỏ.
    if (/40002|finance permission|finance role/i.test(msg)) {
      bcBoQua.push(bcId);
      log("CẢNH BÁO: BC " + bcId + " thiếu quyền finance (40002) — bỏ qua hoá đơn BC này, đo VAT từ BC còn lại.");
      continue;
    }
    throw e;
  }
}
if (bcBoQua.length && bcBoQua.length === bcIds.length) {
  log("CẢNH BÁO: KHÔNG BC nào đọc được hoá đơn (thiếu quyền finance) — VAT rơi về mặc định. " +
    "Cấp lại vai trò finance cho token TikTok Business để đo VAT thật.");
}
const trongKy = (t) => {
  const d = String(t.create_time || "").slice(0, 10);
  return d >= since && d <= until;
};
const hoaDonKy = hoaDonTatCa.filter(trongKy);
const VAT = tinhVat(hoaDonKy);

const advertisers = await layAdvertisers();
log("Quét " + advertisers.length + " advertiser: " + advertisers.map((a) => a.name).join(", "));

const rows = [];
const errors = [];
for (const adv of advertisers) {
  try {
    await kiemTienTe(adv);
    const auction = await keoReport(adv, "/report/integrated/get/", {
      data_level: "AUCTION_CAMPAIGN",
      metrics: JSON.stringify(["campaign_name", "spend"]),
    }, "spend", "auction");
    const gmvMax = await keoReport(adv, "/gmv_max/report/get/", {
      metrics: JSON.stringify(["campaign_name", "cost", "orders", "gross_revenue", "roi"]),
      store_ids: JSON.stringify([CONFIG.tiktok.storeId]),
    }, "cost", "gmv_max");
    if (auction.length || gmvMax.length) {
      log(adv.name + " (" + adv.id + "): auction " + auction.length + " dòng, GMV Max " + gmvMax.length + " dòng");
    }
    rows.push(...auction, ...gmvMax);

    // Breakdown theo sản phẩm: chỉ campaign CÓ CHI trong cửa sổ (campaign 0đ không có gì phân bổ).
    // Đặt SAU rows.push có chủ đích: lỗi ở đây rơi vào catch bên dưới, postRows vẫn ghi Expense,
    // execution vẫn đỏ — chi phí không mất vì một bảng tham khảo.
    const cdCoChi = [...new Set(gmvMax.filter((r) => r.spend > 0).map((r) => r.campaignId))];
    try {
      const landedItem = await keoItemGmvMax(adv, cdCoChi);
      if (landedItem > 0) {
        log(adv.name + ": land " + landedItem + " dòng GMV Max cấp sản phẩm (" + cdCoChi.length + " campaign)");
      }
    } catch (e) {
      // Tiền tố CHỈ cho nhánh này. Chủ shop nhìn execution đỏ phải phân biệt được ngay "hỏng bảng
      // tham khảo" với "hỏng chi phí" — hai thứ đòi hai phản ứng khác hẳn nhau. Chi phí của
      // advertiser này ĐÃ nằm trong `rows` (push ở ngay trên) và `postRows` chạy NGOÀI vòng lặp
      // ⇒ vẫn vào sổ bình thường. Ném tiếp để catch bên dưới gom vào `errors` (execution vẫn đỏ).
      throw new Error("BREAKDOWN THAM KHẢO (không ảnh hưởng chi phí): " + ((e && e.message) || String(e)));
    }
  } catch (e) {
    const msg = (e && e.message) || String(e);
    log("LỖI [" + adv.name + " " + adv.id + "]: " + msg);
    errors.push(adv.name + ": " + msg);
  }
}

// HỢP ĐỒNG MỚI: workflow KHÔNG nhân VAT. Gắn vatRate (đo được) vào TỪNG dòng; app tự tính amount.
// spendExVat = số report CHƯA VAT (Int, >= 0). M6: gửi CẢ dòng 0 để app hạ Expense về 0.
// adType ("auction"|"gmv_max") gửi kèm để app tách refId — thiếu nó thì 1 campaign chạy CẢ 2 loại
// cùng ngày sẽ trùng refId trong 1 payload ⇒ app THROW cả lô (đúng thiết kế) ⇒ execution FAILED.
const rowsGui = rows.map((r) => ({
  date: r.date,
  campaignId: r.campaignId,
  campaignName: r.campaignName,
  adType: r.adType,
  spendExVat: Math.round(r.spend),
  vatRate: VAT,
}));

// Đối chiếu chéo (CHỈ log, không chặn): chi tiêu ước tính gồm VAT vs hoá đơn TikTok đã xuất TRONG KỲ.
// Lệch nhiều là dấu hiệu sai nguồn/sai thuế. Hoá đơn xuất theo NGƯỠNG nên luôn trễ hơn chi tiêu.
const tongChi = rowsGui.reduce((s, r) => s + Math.round(r.spendExVat * (1 + VAT)), 0);
const tongHoaDon = hoaDonKy
  .filter((t) => /BILL|PAYMENT/i.test(String(t.transaction_type)))
  .reduce((s, t) => s + Math.abs(Number(t.amount || 0)), 0);
if (tongHoaDon > 0) {
  const lech = Math.abs(tongChi - tongHoaDon) / tongHoaDon;
  log("Đối chiếu " + since + " → " + until + ": chi tiêu+VAT " + tongChi + "đ vs hoá đơn " + tongHoaDon +
    "đ (lệch " + (lech * 100).toFixed(1) + "%)");
  if (lech > 0.25) {
    log("CẢNH BÁO: lệch > 25% — hoá đơn xuất theo ngưỡng nên trễ, nhưng lệch lớn thế này nên soi lại.");
  }
}

// GHI SỐ TRƯỚC, KÊU LỖI SAU: một advertiser lỗi (vd 429 dai) KHÔNG được làm mất chi phí đã thu của
// các advertiser khác. POST xong mới throw để n8n đánh execution FAILED (chủ shop thấy) — nhưng chi
// phí kỳ này VẪN vào sổ. (Cùng tinh thần meta-ads-nightly: ghi dữ liệu xong rồi mới báo lỗi.)
const summary = [await postRows("TIKTOK_ADS", rowsGui)];
log("Xong cửa sổ " + soNgay + " ngày (" + since + " → " + until + "): " + JSON.stringify(summary));

if (errors.length) {
  throw new Error("tiktok-business-nightly (" + since + " → " + until + ") hỏng " + errors.length + "/" +
    advertisers.length + " advertiser (chi phí thu được ĐÃ ghi vào sổ trước khi báo lỗi):\n- " + errors.join("\n- "));
}

return [
  {
    json: {
      mode: soNgayEp > 0 ? `cửa sổ ép ${soNgayEp} ngày (key tiktokBusinessManualDays)` : "mặc định (nightlyDays)",
      execMode: $execution.mode, // giá trị THẬT n8n trả cho biến này — ghi lại để khỏi phải đoán
      soNgay,
      since,
      until,
      advertisers: advertisers.length,
      businessCenters: bcIds.length,
      vat: VAT,
      hoaDon: hoaDonKy.length,
      summary,
    },
  },
];
